{"code": "import numpy as np
from scipy.integrate import quad
from math import atan

def integrand(x, a, b):
    if x <= 0 or x >= 1:
        return 0.0
    return np.sin(np.log(1/x)) * (x**b - x**a) / np.log(x)

def numerical_integral(a, b):
    # The integral is proper (removable singularities at 0 and 1)
    # But quad handles endpoints well. 
    # However, at x=0, x^a/log x -> 0. At x=1, -> b-a.
    # log(1/x) -> 0. sin(0)=0. So integrand -> 0.
    # We can integrate from 0 to 1 safely.
    val, err = quad(integrand, 0, 1, args=(a, b))
    return val

def analytic_solution(a, b):
    return atan(b + 1) - atan(a + 1)

# Test cases
cases = [(1, 2), (0.5, 1.5), (0.1, 3.2)]

for a, b in cases:
    num_val = numerical_integral(a, b)
    ana_val = analytic_solution(a, b)
    print(f"a={a}, b={b}")
    print(f"  Numerical: {num_val:.10f}")
    print(f"  Analytic:  {ana_val:.10f}")
    print(f"  Diff:      {abs(num_val - ana_val):.2e}")"}
